<style>dialog{margin:auto}dialog::backdrop{background:rgb(15 23 42/.55)}dialog label{display:block;font-size:.75rem;font-weight:700;color:#334155}dialog input,dialog select{display:block;width:100%;margin-top:.35rem;border:1px solid #cbd5e1;border-radius:.65rem;padding:.6rem .7rem;font-size:.875rem}</style>
<script>document.addEventListener('DOMContentLoaded',()=>{const csrf=document.querySelector('meta[name="csrf-token"]').content;const toast=(m,bad=false)=>{let e=document.getElementById('payment-toast');if(!e){e=document.createElement('div');e.id='payment-toast';e.className='fixed right-5 top-20 z-50 rounded-xl px-4 py-3 text-sm font-bold text-white shadow-lg';document.body.append(e)}e.className='fixed right-5 top-20 z-50 rounded-xl px-4 py-3 text-sm font-bold text-white shadow-lg '+(bad?'bg-rose-500':'bg-emerald-500');e.textContent=m;setTimeout(()=>e.remove(),3500)};const refresh=async(panel)=>{let d=new DOMParser().parseFromString(await fetch(location.href,{headers:{'X-Requested-With':'XMLHttpRequest'}}).then(r=>r.text()),'text/html');document.getElementById(panel).innerHTML=d.getElementById(panel).innerHTML};document.addEventListener('click',async e=>{let b=e.target.closest('.delete-item');if(b){if(!confirm(b.dataset.message))return;let r=await fetch(b.dataset.url,{method:'DELETE',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'}}),j=await r.json();if(!r.ok)return toast(j.message,true);await refresh(b.closest('#types')?'types':'accounts');toast(j.message);return}b=e.target.closest('.tab');if(b){let isTypes=b.dataset.panel==='types';document.getElementById('accounts').classList.toggle('hidden',isTypes);document.getElementById('types').classList.toggle('hidden',!isTypes);document.querySelectorAll('.tab').forEach(x=>{x.classList.toggle('border-purple-600',x===b);x.classList.toggle('border-transparent',x!==b)});return}});document.querySelectorAll('#account-form,#type-form').forEach(f=>f.addEventListener('submit',async e=>{e.preventDefault();let r=await fetch(f.action,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:new FormData(f)}),j=await r.json();if(!r.ok)return toast(j.message||'Please correct the form.',true);f.closest('dialog').close();await refresh(f.id==='type-form'?'types':'accounts');toast(j.message)}));document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close())})</script>
@endpush
