<script>document.addEventListener('click',async event=>{const button=event.target.closest('.close-account');if(!button)return;const confirmation=document.getElementById('close-confirm');document.getElementById('close-confirm').querySelector('h3').textContent='Close '+button.dataset.name+'?';const accepted=await new Promise(resolve=>{const yes=document.getElementById('close-ok'),no=document.getElementById('close-cancel');const finish=value=>{yes.onclick=null;no.onclick=null;confirmation.close();resolve(value)};yes.onclick=()=>finish(true);no.onclick=()=>finish(false);confirmation.showModal()});if(!accepted)return;const response=await fetch(button.dataset.url,{method:'PUT',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,Accept:'application/json'}});const result=await response.json();if(!response.ok){alert(result.message||'Unable to close account.');return}const page=await fetch(location.href),doc=new DOMParser().parseFromString(await page.text(),'text/html');document.getElementById('accounts').innerHTML=doc.getElementById('accounts').innerHTML;document.getElementById('account-state').value='active';document.getElementById('account-state').dispatchEvent(new Event('change',{bubbles:true}));});</script>
@endpush
@push('scripts')
<script>document.addEventListener('click',e=>{const a=e.target.closest('#add-account,.edit-account'),t=e.target.closest('#add-type,.edit-type');if(a){const f=document.getElementById('account-form'),v=a.dataset.a?JSON.parse(a.dataset.a):null;f.reset();f.action=a.dataset.url||@json(route('payment-accounts.store'));f.elements._method.value=v?'PUT':'POST';
document.getElementById('account-heading').textContent=v?'Edit Account':'Add Account';
f.querySelector('footer button:not([type="button"])').textContent=v?'Update':'Save';
const sub=f.elements.payment_account_sub_type_id;
sub.replaceChildren(new Option('Please Select',''));
sub.disabled=true;
if(v){
    ['name','account_number','payment_account_type_id','opening_balance'].forEach(k=>f.elements[k].value=v[k]??'');
    if(v.sub_type){
        sub.add(new Option(v.sub_type.name,v.sub_type.id));
        sub.disabled=false;
        sub.value=v.payment_account_sub_type_id;
    }
    (v.details||[]).slice(0,2).forEach((detail,i)=>{
        f.elements['details['+i+'][label]'].value=detail.label;
        f.elements['details['+i+'][value]'].value=detail.value;
    });
}
document.getElementById('account-modal').showModal()}if(t){const f=document.getElementById('type-form'),v=t.dataset.t?JSON.parse(t.dataset.t):null;f.reset();f.action=v?@json(url('/payment-accounts/types'))+'/'+v.id:@json(route('payment-accounts.types.store'));f.elements._method.value=v?'PUT':'POST';if(v){f.elements.name.value=v.name;f.elements.parent_id.value=v.parent_id||''}document.getElementById('type-modal').showModal()}})</script>
@endpush
