<script>document.addEventListener('DOMContentLoaded',()=>{const syncTypes=async()=>{const html=await fetch(@json(route('payment-accounts.index')),{headers:{'X-Requested-With':'XMLHttpRequest'}}).then(r=>r.text()),doc=new DOMParser().parseFromString(html,'text/html');[['#type-form select[name="parent_id"]','#type-form select[name="parent_id"]'],['#parent-type','#parent-type']].forEach(([target,source])=>{const current=document.querySelector(target),fresh=doc.querySelector(source);if(!current||!fresh)return;const selected=current.value;current.innerHTML=fresh.innerHTML;current.value=selected})};['mousedown','focus'].forEach(event=>{document.querySelector('#type-form select[name="parent_id"]').addEventListener(event,syncTypes);document.getElementById('parent-type').addEventListener(event,syncTypes)})})</script>
@endpush
@push('scripts')
<script>document.addEventListener('DOMContentLoaded',()=>{const parent=document.getElementById('parent-type'),sub=document.getElementById('sub-type');parent.addEventListener('change',async()=>{sub.innerHTML='<option value="">Loading…</option>';sub.disabled=true;const roots=await fetch(@json(route('payment-accounts.types.options'))).then(r=>r.json());const selected=roots.find(type=>String(type.id)===String(parent.value));const children=selected?.children??[];sub.innerHTML='<option value="">Please Select</option>'+children.map(type=>'<option value="'+type.id+'">'+type.name+'</option>').join('');sub.disabled=children.length===0})})</script>
@endpush
@push('scripts')
<script>document.addEventListener('DOMContentLoaded',()=>{const filter=()=>{const state=document.getElementById('account-state')?.value||'all',term=(document.getElementById('account-search')?.value||'').toLowerCase();let total=0;document.querySelectorAll('.account-row').forEach(row=>{const visible=(state==='all'||row.dataset.state===state)&&row.textContent.toLowerCase().includes(term);row.hidden=!visible;if(visible){const balance=(row.children[4]?.textContent||'').replace(/,/g,'').match(/-?\d+(?:\.\d+)?/);total+=balance?Number(balance[0]):0}});const cell=document.querySelector('#accounts tfoot td:nth-child(2)');if(cell)cell.textContent='Rs. '+total.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})};document.addEventListener('change',e=>{if(e.target.id==='account-state')filter()});document.addEventListener('input',e=>{if(e.target.id==='account-search')filter()});new MutationObserver(filter).observe(document.getElementById('accounts'),{childList:true});filter()})</script>
@endpush
