<script>document.addEventListener('click',async e=>{const b=e.target.closest('.delete-item');if(!b)return;e.stopImmediatePropagation();if(!confirm(b.dataset.message))return;const r=await fetch(b.dataset.url,{method:'DELETE',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'Accept':'application/json'}}),j=await r.json();if(!r.ok){alert(j.message);return}const id=b.dataset.typeId;if(id)document.querySelectorAll('#parent-type option,#sub-type option,#type-form select[name="parent_id"] option').forEach(o=>{if(o.value===id)o.remove()});b.closest('tr').remove()},true)</script>
